		{Suffrage: Voter, ID: leader.id, Address: leader.addr},
		{Suffrage: Voter, ID: near.id, Address: near.addr},
		{Suffrage: Voter, ID: nodes[2].id, Address: nodes[2].addr},
		{Suffrage: Voter, ID: nodes[3].id, Address: nodes[3].addr},
	}}
