			"last_index":   n.raft.LastIndex(),
			"leader_hb_ms": leaderHB.Milliseconds(),
			"near_hb_ms":   nearHB.Milliseconds(),
			"far_hb_ms":    farHB.Milliseconds(),
			"waited_baseline": waitBaseline,
		})
	}

	demoteAt := time.Now()
	demoteErr := leader.raft.DemoteVoter(near.id, 0, 10*time.Second).Error()
	committedAt := time.Now()
	configIndex := leader.raft.LastIndex()

	type nodeObs struct {
		converged     bool
		convergedMs   int64
		staleObserved bool
		staleMaxIndex uint64
	}
