func caEmit(ev map[string]interface{}) {
	b, err := json.Marshal(ev)
	if err != nil {
		panic(err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

func caErrString(err error) string {
	if err == nil {
		return "nil"
	}
	return err.Error()
}

type caNode struct {
